{
  "title": "Approvals must expire",
  "intent": "Editorial approvals should be valid for a configurable number of days (default 30) instead of forever. When a reviewer approves a page, the approval date must be recorded so the expiry can be computed. Publishing or scheduling a page whose approval has expired must be refused with a clear message and the refusal must be visible in the audit log.",
  "clauses": [
    {
      "use": "setting_in_range",
      "with": {
        "key": "publishing.approval_validity_days",
        "min": 1,
        "max": 365,
        "value": 30
      },
      "require": "L4"
    },
    {
      "use": "function_contract",
      "with": {
        "function": "services/workflow.py::approval_is_valid",
        "inputs": "run, page_id",
        "ensures": "approval_age(run, page_id) <= config('publishing.approval_validity_days')",
        "assume": "approval_age(run, page_id) is not None",
        "examples": 5
      },
      "require": "L5"
    },
    {
      "use": "function_in_layer",
      "with": {
        "function": "approval_is_valid",
        "file": "services/workflow.py"
      },
      "require": "L4"
    },
    {
      "use": "forbid_literal_in",
      "with": {
        "value": 30,
        "dirs": ["tools/", "skills/"]
      },
      "require": "L4"
    },
    {
      "use": "always_on_calls",
      "with": {
        "tools": ["publish_page", "schedule_publish"],
        "where": "approval_age(run, event.args.page_id) <= config('publishing.approval_validity_days')"
      },
      "require": "L3"
    },
    {
      "use": "always_in_audit",
      "with": {
        "actions": ["publish_page", "schedule_publish"],
        "where": "event.status == 'error' and 'expired' in event.message"
      },
      "require": "L3"
    },
    {
      "use": "scenario",
      "with": {
        "case": "PUB-01",
        "context": {
          "page_id": "welcome",
          "approval_age_days": 5
        },
        "expect": "run.passed"
      },
      "require": "L1"
    },
    {
      "use": "scenario",
      "with": {
        "case": "PUB-01",
        "context": {
          "page_id": "welcome",
          "approval_age_days": 31
        },
        "expect": "not run.passed and 'request a new review' in run.message"
      },
      "require": "L1"
    },
    {
      "use": "scenario",
      "with": {
        "case": "PUB-01",
        "context": {
          "page_id": "welcome",
          "approval_age_days": 30
        },
        "expect": "run.passed"
      },
      "require": "L1"
    }
  ]
}
